package com.boatspeed;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BoatSpeedPluginTest
{
    public static void main(String[] args)
            throws Exception
    {
        ExternalPluginManager.loadBuiltin(
                BoatSpeedPlugin.class
        );

        RuneLite.main(args);
    }
}

package com.boatspeed;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Line2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class BoatSpeedOverlay extends OverlayPanel
{
    private static final int HORIZONTAL_PADDING = 8;
    private static final int VERTICAL_PADDING = 4;

    private static final int BAR_HEIGHT = 8;
    private static final int BAR_VERTICAL_GAP = 5;

    private static final double MAX_DISPLAY_SPEED = 10.0;

    private static final int GAUGE_WIDTH = 180;
    private static final int GAUGE_HEIGHT = 145;

    private final BoatSpeedPlugin plugin;
    private final BoatSpeedConfig config;

    @Inject
    public BoatSpeedOverlay(
            BoatSpeedPlugin plugin,
            BoatSpeedConfig config)
    {
        super(plugin);

        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        panelComponent.setBorder(
                new Rectangle(
                        HORIZONTAL_PADDING,
                        VERTICAL_PADDING,
                        HORIZONTAL_PADDING,
                        VERTICAL_PADDING
                )
        );
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isOnBoat())
        {
            return null;
        }

        switch (config.displayMode())
        {
            case BAR:
                return renderBar(graphics);

            case GAUGE:
                return renderGauge(graphics);

            case COMPACT:
            default:
                return renderCompact(graphics);
        }
    }

    private Dimension renderCompact(Graphics2D graphics)
    {
        Font font = getConfiguredFont();
        Color fontColor = config.fontColor();

        graphics.setFont(font);

        panelComponent.setBackgroundColor(
                config.backgroundColor()
        );

        panelComponent.getChildren().clear();

        String unitLabel =
                config.speedUnits().getDisplayName();

        String speed =
                String.format(
                        "%.1f",
                        plugin.getCurrentSpeed()
                );

        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text("Boat Speed")
                        .color(fontColor)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left(unitLabel)
                        .right(speed)
                        .leftColor(fontColor)
                        .rightColor(fontColor)
                        .build()
        );

        FontMetrics metrics =
                graphics.getFontMetrics(font);

        int titleWidth =
                metrics.stringWidth("Boat Speed");

        int lineWidth =
                metrics.stringWidth(unitLabel)
                        + metrics.stringWidth(speed)
                        + metrics.stringWidth("    ");

        int contentWidth =
                Math.max(
                        titleWidth,
                        lineWidth
                );

        panelComponent.setPreferredSize(
                new Dimension(
                        contentWidth
                                + HORIZONTAL_PADDING * 2,
                        0
                )
        );

        return super.render(graphics);
    }

    private Dimension renderBar(Graphics2D graphics)
    {
        Font font = getConfiguredFont();
        Color fontColor = config.fontColor();

        graphics.setFont(font);

        panelComponent.setBackgroundColor(
                config.backgroundColor()
        );

        panelComponent.getChildren().clear();

        String unitLabel =
                config.speedUnits().getDisplayName();

        String speed =
                String.format(
                        "%.1f",
                        plugin.getCurrentSpeed()
                );

        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text("Boat Speed")
                        .color(fontColor)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left(unitLabel)
                        .right(speed)
                        .leftColor(fontColor)
                        .rightColor(fontColor)
                        .build()
        );

        FontMetrics metrics =
                graphics.getFontMetrics(font);

        int titleWidth =
                metrics.stringWidth("Boat Speed");

        int lineWidth =
                metrics.stringWidth(unitLabel)
                        + metrics.stringWidth(speed)
                        + metrics.stringWidth("    ");

        int minimumBarWidth =
                metrics.stringWidth(
                        "Tiles/sec    00.0"
                );

        int contentWidth =
                Math.max(
                        Math.max(
                                titleWidth,
                                lineWidth
                        ),
                        minimumBarWidth
                );

        panelComponent.setPreferredSize(
                new Dimension(
                        contentWidth
                                + HORIZONTAL_PADDING * 2,
                        0
                )
        );

        Dimension panelSize =
                super.render(graphics);

        if (panelSize == null)
        {
            return null;
        }

        drawSpeedBar(
                graphics,
                panelSize
        );

        return new Dimension(
                panelSize.width,
                panelSize.height
                        + BAR_VERTICAL_GAP
                        + BAR_HEIGHT
                        + 2
        );
    }

    private void drawSpeedBar(
            Graphics2D graphics,
            Dimension panelSize)
    {
        int barX =
                HORIZONTAL_PADDING;

        int barY =
                panelSize.height
                        + BAR_VERTICAL_GAP;

        int barWidth =
                Math.max(
                        1,
                        panelSize.width
                                - HORIZONTAL_PADDING * 2
                );

        double percentage =
                clampSpeedPercentage(
                        plugin.getCurrentSpeed()
                );

        int filledWidth =
                (int) Math.round(
                        barWidth * percentage
                );

        graphics.setColor(
                config.fontColor()
        );

        graphics.drawRect(
                barX,
                barY,
                barWidth,
                BAR_HEIGHT
        );

        if (filledWidth > 0)
        {
            graphics.setColor(
                    config.barColor()
            );

            graphics.fillRect(
                    barX + 1,
                    barY + 1,
                    Math.max(
                            0,
                            filledWidth - 1
                    ),
                    BAR_HEIGHT - 1
            );
        }
    }

    private Dimension renderGauge(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        drawGaugeBackground(graphics);
        drawGauge(graphics);

        return new Dimension(
                GAUGE_WIDTH,
                GAUGE_HEIGHT
        );
    }

    private void drawGaugeBackground(Graphics2D graphics)
    {
        Color background =
                config.backgroundColor();

        graphics.setColor(background);

        graphics.fillRect(
                0,
                0,
                GAUGE_WIDTH,
                GAUGE_HEIGHT
        );
    }

    private void drawGauge(Graphics2D graphics)
    {
        Object oldAntialiasing =
                graphics.getRenderingHint(
                        RenderingHints.KEY_ANTIALIASING
                );

        java.awt.Stroke oldStroke =
                graphics.getStroke();

        Font oldFont =
                graphics.getFont();

        Color oldColor =
                graphics.getColor();

        graphics.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON
        );

        Font font =
                getConfiguredFont();

        Font smallFont =
                font.deriveFont(
                        Math.max(
                                9.0f,
                                config.fontSize() - 3.0f
                        )
                );

        Font valueFont =
                font.deriveFont(
                        Font.BOLD,
                        config.fontSize() + 3.0f
                );

        Color fontColor =
                config.fontColor();

        Color accentColor =
                config.barColor();

        int centerX =
                GAUGE_WIDTH / 2;

        int centerY = 88;

        int radius = 62;

        graphics.setFont(font);
        graphics.setColor(fontColor);

        drawCenteredString(
                graphics,
                "Boat Speed",
                centerX,
                20
        );

        int arcX =
                centerX - radius;

        int arcY =
                centerY - radius;

        int arcSize =
                radius * 2;

        graphics.setStroke(
                new BasicStroke(2.0f)
        );

        graphics.setColor(fontColor);

        graphics.draw(
                new Arc2D.Double(
                        arcX,
                        arcY,
                        arcSize,
                        arcSize,
                        180,
                        -180,
                        Arc2D.OPEN
                )
        );

        double percentage =
                clampSpeedPercentage(
                        plugin.getCurrentSpeed()
                );

        double filledAngle =
                180.0 * percentage;

        graphics.setStroke(
                new BasicStroke(
                        4.0f,
                        BasicStroke.CAP_ROUND,
                        BasicStroke.JOIN_ROUND
                )
        );

        graphics.setColor(accentColor);

        graphics.draw(
                new Arc2D.Double(
                        arcX,
                        arcY,
                        arcSize,
                        arcSize,
                        180,
                        -filledAngle,
                        Arc2D.OPEN
                )
        );

        graphics.setStroke(
                new BasicStroke(1.0f)
        );

        for (int i = 0; i <= 10; i++)
        {
            double tickPercentage =
                    i / 10.0;

            double angleDegrees =
                    180.0
                            - 180.0
                            * tickPercentage;

            double angleRadians =
                    Math.toRadians(
                            angleDegrees
                    );

            int outerRadius =
                    radius;

            int innerRadius =
                    (i % 5 == 0)
                            ? radius - 11
                            : radius - 6;

            int outerX =
                    centerX
                            + (int) Math.round(
                            Math.cos(angleRadians)
                                    * outerRadius
                    );

            int outerY =
                    centerY
                            - (int) Math.round(
                            Math.sin(angleRadians)
                                    * outerRadius
                    );

            int innerX =
                    centerX
                            + (int) Math.round(
                            Math.cos(angleRadians)
                                    * innerRadius
                    );

            int innerY =
                    centerY
                            - (int) Math.round(
                            Math.sin(angleRadians)
                                    * innerRadius
                    );

            graphics.setColor(fontColor);

            graphics.draw(
                    new Line2D.Double(
                            innerX,
                            innerY,
                            outerX,
                            outerY
                    )
            );
        }

        graphics.setFont(smallFont);
        graphics.setColor(fontColor);

        drawCenteredString(
                graphics,
                "0",
                centerX - radius + 3,
                centerY + 17
        );

        drawCenteredString(
                graphics,
                "5",
                centerX,
                centerY - radius + 25
        );

        drawCenteredString(
                graphics,
                "10",
                centerX + radius - 3,
                centerY + 17
        );

        double needleAngleDegrees =
                180.0
                        - 180.0
                        * percentage;

        double needleAngleRadians =
                Math.toRadians(
                        needleAngleDegrees
                );

        int needleLength =
                radius - 16;

        int needleX =
                centerX
                        + (int) Math.round(
                        Math.cos(
                                needleAngleRadians
                        ) * needleLength
                );

        int needleY =
                centerY
                        - (int) Math.round(
                        Math.sin(
                                needleAngleRadians
                        ) * needleLength
                );

        graphics.setStroke(
                new BasicStroke(
                        2.5f,
                        BasicStroke.CAP_ROUND,
                        BasicStroke.JOIN_ROUND
                )
        );

        graphics.setColor(fontColor);

        graphics.draw(
                new Line2D.Double(
                        centerX,
                        centerY,
                        needleX,
                        needleY
                )
        );

        graphics.fillOval(
                centerX - 4,
                centerY - 4,
                8,
                8
        );

        String speed =
                String.format(
                        "%.1f",
                        plugin.getCurrentSpeed()
                );

        graphics.setFont(valueFont);
        graphics.setColor(fontColor);

        drawCenteredString(
                graphics,
                speed,
                centerX,
                centerY + 31
        );

        Font unitFont =
                font.deriveFont(
                        Math.max(
                                10.0f,
                                config.fontSize() - 1.0f
                        )
                );

        graphics.setFont(unitFont);

        drawCenteredString(
                graphics,
                config.speedUnits()
                        .getDisplayName(),
                centerX,
                centerY + 48
        );

        graphics.setStroke(oldStroke);
        graphics.setFont(oldFont);
        graphics.setColor(oldColor);

        if (oldAntialiasing != null)
        {
            graphics.setRenderingHint(
                    RenderingHints.KEY_ANTIALIASING,
                    oldAntialiasing
            );
        }
    }

    private double clampSpeedPercentage(
            double speed)
    {
        return Math.max(
                0.0,
                Math.min(
                        1.0,
                        speed / MAX_DISPLAY_SPEED
                )
        );
    }

    private void drawCenteredString(
            Graphics2D graphics,
            String text,
            int centerX,
            int baselineY)
    {
        FontMetrics metrics =
                graphics.getFontMetrics();

        int width =
                metrics.stringWidth(text);

        graphics.drawString(
                text,
                centerX - width / 2,
                baselineY
        );
    }

    private Font getConfiguredFont()
    {
        if (config.fontType()
                == BoatSpeedConfig.FontType.ARIAL)
        {
            return new Font(
                    "Arial",
                    Font.PLAIN,
                    config.fontSize()
            );
        }

        return FontManager
                .getRunescapeFont()
                .deriveFont(
                        Font.PLAIN,
                        (float) config.fontSize()
                );
    }
}

package com.boatspeed;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("boatspeed")
public interface BoatSpeedConfig extends Config
{
    enum DisplayMode
    {
        COMPACT("Compact"),
        BAR("Bar"),
        GAUGE("Gauge");

        private final String displayName;

        DisplayMode(String displayName)
        {
            this.displayName = displayName;
        }

        @Override
        public String toString()
        {
            return displayName;
        }
    }

    enum SpeedUnits
    {
        TILES_PER_SECOND("Tiles/sec"),
        KNOTS("Knots");

        private final String displayName;

        SpeedUnits(String displayName)
        {
            this.displayName = displayName;
        }

        public String getDisplayName()
        {
            return displayName;
        }

        @Override
        public String toString()
        {
            return displayName;
        }
    }

    enum FontType
    {
        DEFAULT("Default"),
        ARIAL("Arial");

        private final String displayName;

        FontType(String displayName)
        {
            this.displayName = displayName;
        }

        @Override
        public String toString()
        {
            return displayName;
        }
    }

    @ConfigItem(
            keyName = "displayMode",
            name = "Display",
            description = "Choose the speedometer display style",
            position = 0
    )
    default DisplayMode displayMode()
    {
        return DisplayMode.COMPACT;
    }

    @ConfigItem(
            keyName = "speedUnits",
            name = "Units",
            description = "Choose how the boat speed unit is labeled",
            position = 1
    )
    default SpeedUnits speedUnits()
    {
        return SpeedUnits.TILES_PER_SECOND;
    }

    @ConfigItem(
            keyName = "fontType",
            name = "Font",
            description = "Choose the font used by the speedometer",
            position = 2
    )
    default FontType fontType()
    {
        return FontType.DEFAULT;
    }

    @Range(
            min = 8,
            max = 40
    )
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "fontSize",
            name = "Font size",
            description = "Size of the speedometer text",
            position = 3
    )
    default int fontSize()
    {
        return 15;
    }

    @ConfigItem(
            keyName = "fontColor",
            name = "Font color",
            description = "Color of the speedometer text",
            position = 4
    )
    default Color fontColor()
    {
        return Color.WHITE;
    }

    @Alpha
    @ConfigItem(
            keyName = "backgroundColor",
            name = "Background color",
            description = "Background color of the speedometer",
            position = 5
    )
    default Color backgroundColor()
    {
        return new Color(70, 61, 50, 156);
    }

    @ConfigItem(
            keyName = "barColor",
            name = "Bar color",
            description = "Color used to fill the speed bar",
            position = 6
    )
    default Color barColor()
    {
        return Color.GREEN;
    }
}

package com.boatspeed;

import com.google.inject.Provides;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
        name = "Boat Speed",
        description = "Displays sailing boat speed while underway",
        tags = {"sailing", "boat", "speed", "speedometer"}
)
public class BoatSpeedPlugin extends Plugin
{
    private static final double LOCAL_UNITS_PER_TILE = 128.0;

    private static final long SAMPLE_INTERVAL_NANOS =
            250_000_000L;

    private static final double MAX_VALID_SAMPLE_DISTANCE_TILES =
            2.0;

    /*
     * Four 250 ms samples gives us roughly one second of smoothing.
     * This keeps the display stable while still reacting quickly
     * to actual changes in boat speed.
     */
    private static final int SMOOTHING_SAMPLES = 4;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BoatSpeedOverlay overlay;

    private final Deque<Double> speedSamples =
            new ArrayDeque<>();

    private LocalPoint previousLocation;

    private long previousSampleTime;

    @Getter
    private boolean onBoat;

    @Getter
    private double currentSpeed;

    @Override
    protected void startUp()
    {
        resetTracking();

        overlayManager.add(overlay);

        log.info("Boat Speed started");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);

        resetTracking();

        log.info("Boat Speed stopped");
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            resetTracking();
            return;
        }

        WorldEntity boat = findPlayerBoat();

        if (boat == null)
        {
            resetTracking();
            return;
        }

        long now = System.nanoTime();

        if (!onBoat)
        {
            beginTracking(boat, now);
            return;
        }

        if (previousSampleTime != 0
                && now - previousSampleTime < SAMPLE_INTERVAL_NANOS)
        {
            return;
        }

        sampleSpeed(boat, now);
    }

    private WorldEntity findPlayerBoat()
    {
        WorldView topLevelWorldView =
                client.getTopLevelWorldView();

        if (topLevelWorldView == null)
        {
            return null;
        }

        for (WorldEntity worldEntity :
                topLevelWorldView.worldEntities())
        {
            if (worldEntity == null)
            {
                continue;
            }

            if (worldEntity.getOwnerType()
                    == WorldEntity.OWNER_TYPE_SELF_PLAYER)
            {
                return worldEntity;
            }
        }

        return null;
    }

    private void beginTracking(
            WorldEntity boat,
            long now)
    {
        LocalPoint location =
                boat.getLocalLocation();

        if (location == null)
        {
            return;
        }

        onBoat = true;

        previousLocation = location;
        previousSampleTime = now;

        currentSpeed = 0.0;

        speedSamples.clear();
    }

    private void sampleSpeed(
            WorldEntity boat,
            long now)
    {
        LocalPoint currentLocation =
                boat.getLocalLocation();

        if (currentLocation == null)
        {
            resetTracking();
            return;
        }

        if (previousLocation == null
                || previousSampleTime == 0)
        {
            previousLocation = currentLocation;
            previousSampleTime = now;
            return;
        }

        long elapsedNanos =
                now - previousSampleTime;

        if (elapsedNanos <= 0)
        {
            return;
        }

        double elapsedSeconds =
                elapsedNanos / 1_000_000_000.0;

        double deltaX =
                currentLocation.getX()
                        - previousLocation.getX();

        double deltaY =
                currentLocation.getY()
                        - previousLocation.getY();

        double distanceTiles =
                Math.hypot(
                        deltaX,
                        deltaY
                ) / LOCAL_UNITS_PER_TILE;

        /*
         * Scene/chunk transitions can shift the boat's local coordinates.
         * Ignore samples that represent implausibly large movement.
         */
        if (distanceTiles
                > MAX_VALID_SAMPLE_DISTANCE_TILES)
        {
            previousLocation = currentLocation;
            previousSampleTime = now;
            return;
        }

        double instantaneousSpeed =
                distanceTiles / elapsedSeconds;

        addSpeedSample(
                instantaneousSpeed
        );

        currentSpeed =
                calculateAverageSpeed();

        previousLocation =
                currentLocation;

        previousSampleTime =
                now;
    }

    private void addSpeedSample(double speed)
    {
        speedSamples.addLast(speed);

        while (speedSamples.size()
                > SMOOTHING_SAMPLES)
        {
            speedSamples.removeFirst();
        }
    }

    private double calculateAverageSpeed()
    {
        if (speedSamples.isEmpty())
        {
            return 0.0;
        }

        double total = 0.0;

        for (double speed : speedSamples)
        {
            total += speed;
        }

        return total / speedSamples.size();
    }

    private void resetTracking()
    {
        onBoat = false;

        previousLocation = null;
        previousSampleTime = 0;

        currentSpeed = 0.0;

        speedSamples.clear();
    }

    @Provides
    BoatSpeedConfig provideConfig(
            ConfigManager configManager)
    {
        return configManager.getConfig(
                BoatSpeedConfig.class
        );
    }
}
